from pathlib import Path
p=Path('work/campaign-complete-1114/pending')
def change(file,old,new):
    path=p/file
    s=path.read_text(encoding='utf-8-sig')
    assert old in s, (file,old)
    path.write_text(s.replace(old,new),encoding='utf-8')
